"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Dict, List, Optional, Union

from pydantic import BaseModel, ConfigDict, ValidationError, field_validator, model_validator


def _to_decimal_2dp(value: Any, *, field_name: str, allow_zero: bool) -> Decimal:
    # Accept str/int/float; reject other types via Decimal conversion rules.
    try:
        d = Decimal(str(value))
    except Exception as e:  # noqa: BLE001
        raise ValueError(f"{field_name} must be a number") from e

    if allow_zero:
        if d < Decimal("0"):
            raise ValueError(f"{field_name} must be >= 0")
    else:
        if d <= Decimal("0"):
            raise ValueError(f"{field_name} must be > 0")

    # Ensure exactly 2 decimals in output by quantizing.
    # (If input has more decimals, quantize will round; this matches "string with exactly two decimals".)
    try:
        d = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except Exception as e:  # noqa: BLE001
        raise ValueError(f"{field_name} must be representable with 2 decimals") from e

    return d


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    model_config = ConfigDict(extra="forbid")

    @field_validator("quantity", mode="before")
    @classmethod
    def _parse_quantity(cls, v: Any) -> Any:
        # Let pydantic convert string->int where sensible, but enforce >= 1.
        if isinstance(v, bool):
            # Avoid bool being treated as int.
            raise ValueError("quantity must be an integer")
        try:
            q = int(v)
        except Exception as e:  # noqa: BLE001
            raise ValueError("quantity must be an integer") from e
        if q < 1:
            raise ValueError("quantity must be >= 1")
        return q

    @field_validator("unit_price", mode="before")
    @classmethod
    def _parse_unit_price(cls, v: Any) -> Any:
        # unit_price >= 0
        return _to_decimal_2dp(v, field_name="unit_price", allow_zero=True)

    def unit_price_str(self) -> str:
        # Always exactly two decimals
        return f"{self.unit_price:.2f}"

    def line_total(self) -> Decimal:
        return (self.unit_price * Decimal(self.quantity)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    # total as Decimal for calculation; will be dumped as string
    total: Decimal

    model_config = ConfigDict(extra="forbid")

    @field_validator("issued_at", mode="before")
    @classmethod
    def _parse_issued_at(cls, v: Any) -> datetime:
        # Accept ISO 8601 string or datetime. Naive datetime is treated as UTC.
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                # datetime.fromisoformat doesn't handle "Z" in all cases; normalize.
                s = v.strip()
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.fromisoformat(s)
            except Exception as e:  # noqa: BLE001
                raise ValueError("issued_at must be an ISO 8601 string") from e
        else:
            raise ValueError("issued_at must be an ISO 8601 string or datetime")

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)

        return dt.astimezone(timezone.utc)

    @model_validator(mode="after")
    def _compute_total(self) -> "Invoice":
        total = Decimal("0.00")
        for line in self.lines:
            total += line.line_total()
        total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        self.total = total
        return self

    def model_dump_for_billing(self) -> Dict[str, Any]:
        # Format issued_at exactly: YYYY-MM-DDTHH:MM:SSZ
        issued_at_utc = self.issued_at.astimezone(timezone.utc)
        issued_at_str = issued_at_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

        return {
            "number": self.number,
            "issued_at": issued_at_str,
            "lines": [
                {"sku": line.sku, "quantity": line.quantity, "unit_price": line.unit_price_str()}
                for line in self.lines
            ],
            "total": f"{self.total:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate an invoice and return its JSON text for the billing API.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of { sku: str, quantity: int >= 1, unit_price: decimal >= 0 as str/int/float }

    Output JSON object includes:
      - number
      - issued_at formatted as "YYYY-MM-DDTHH:MM:SSZ" in UTC
      - lines: { sku, quantity, unit_price } where unit_price is a string with exactly two decimals
      - total: string with two decimals (sum of quantity * unit_price)

    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # Contract: raise ValueError for invalid input.
        raise ValueError("invalid invoice input") from e

    return __import__("json").dumps(invoice.model_dump_for_billing(), separators=(",", ":"))

from __future__ import annotations

from pydantic import BaseModel, Field, field_validator

from signup_form import PhoneNumber, _USERNAME_RE  # type: ignore[attr-defined]
from signup_form import SignupForm  # noqa: F401


class _ValidateEmail(BaseModel):
    username: str = Field(..., pattern=_USERNAME_RE)
    email: str
    phone: PhoneNumber
    password: str = Field(..., min_length=8)
    password_confirm: str

    @field_validator("email", mode="before")
    @classmethod
    def _strip_and_lower_email(cls, v: object) -> str:
        if not isinstance(v, str):
            # Let pydantic raise a validation error -> ValueError for callers.
            raise ValueError("email must be a string")
        return v.strip().lower()

    @field_validator("password_confirm")
    @classmethod
    def _password_confirm_required(cls, v: object) -> object:
        # Presence is enforced by pydantic; this is just clarity.
        return v

    @classmethod
    def model_validate(cls, obj: object, **kwargs):  # pragma: no cover
        return super().model_validate(obj, **kwargs)


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload and return:
      {"username": ..., "email": ..., "phone": <compact phone>}

    Raises ValueError on any missing/invalid field (via pydantic ValidationError).
    """
    # Use the shared phone/username/password rules from the shared library,
    # while enforcing email normalization as requested.
    model = _ValidateEmail.model_validate(data)

    return {
        "username": model.username,
        "email": model.email,
        "phone": str(model.phone),  # PhoneNumber is stored in compact form
    }
